#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
ssh desk 'cd mcmc_splatting_gpu_20261024 && nsys --version > results/graph_profile/versions.txt && /opt/nvidia/nsight-compute/2024.1.1/ncu --version >> results/graph_profile/versions.txt && nsys profile --force-overwrite=true --sample=none --cpuctxsw=none --trace=cuda,nvtx --capture-range=cudaProfilerApi --capture-range-end=stop -o results/graph_profile/adam_optimized ./graph_fit_fma --mode 0 --warp-roi 1 --verify-threads 12 --profile-range 1 --steps 8000 --output results/graph_profile/adam_optimized > results/graph_profile/optimized_nsys.log 2>&1 && nsys stats --report cuda_api_sum,cuda_gpu_kern_sum,cuda_gpu_mem_time_sum --format csv --output results/graph_profile/adam_optimized results/graph_profile/adam_optimized.nsys-rep > results/graph_profile/optimized_stats.log 2>&1'
ssh desk 'cd mcmc_splatting_gpu_20261024 && nsys profile --force-overwrite=true --sample=none --cpuctxsw=none --trace=cuda,nvtx --cuda-graph-trace=node --capture-range=cudaProfilerApi --capture-range-end=stop -o results/graph_profile/adam_graph32 ./graph_fit_fma --mode 0 --warp-roi 1 --graph-batch 32 --verify-threads 12 --profile-range 1 --steps 8000 --output results/graph_profile/adam_graph32 > results/graph_profile/graph32_nsys.log 2>&1 && nsys stats --report cuda_api_sum,cuda_gpu_kern_sum,cuda_gpu_mem_time_sum --format csv --output results/graph_profile/adam_graph32 results/graph_profile/adam_graph32.nsys-rep > results/graph_profile/graph32_stats.log 2>&1'
ssh desk 'cd mcmc_splatting_gpu_20261024 && sudo -n /opt/nvidia/nsight-compute/2024.1.1/ncu --target-processes all --kernel-name "regex:renderWarp|refineAdamScaledWarp" --launch-skip 8000 --launch-count 2 --section SpeedOfLight --section ComputeWorkloadAnalysis --section InstructionStats --section WarpStateStats --section Occupancy --clock-control none --cache-control none --csv ./graph_fit_fma --mode 0 --warp-roi 1 --verify-threads 12 --steps 8000 --output results/graph_profile/optimized_ncu > results/graph_profile/optimized_ncu.csv 2> results/graph_profile/optimized_ncu.log'
scp -q 'desk:mcmc_splatting_gpu_20261024/results/graph_profile/*' results/desk_graph/
echo COPIED
